template<typename T, typename CharT=char>
class ostream_iterator {
    std::basic_ostream<CharT>* stream_;
    const CharT* delimiter_;

public:
    using value_type = void;
    using difference_type = void;
    using pointer = void;
    using reference = void;
    using iterator_category = std::output_iterator_tag;

    ostream_iterator(std::basic_ostream<CharT>& s, const CharT* d)
        : stream_(&s), delimiter_(d) {}

    // Key implementation detail: assignment performs the output
    ostream_iterator& operator=(const T& value) {
        *stream_ << value;
        if (delimiter_) *stream_ << delimiter_;
        return *this;
    }

    ostream_iterator& operator*() { return *this; }
    ostream_iterator& operator++() { return *this; }
    ostream_iterator& operator++(int) { return *this; }
};
